//! Joint error codes as reported in `error_code_current` of the realtime stream and in
//! `error_status` of a joint node. Table recovered from the vendor SDK (60 entries).
//! Codes 1..=0x2000 are warnings and errors of the joint boards; `0` means no active error.

/// Severity of an error code.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Severity {
    Warning,
    Error,
    /// Error that stops the joint after the current motion.
    DeferredStop,
    /// Error that stops the joint immediately.
    ImmediateStop,
    Fatal,
    Other(&'static str),
}

/// How an error code is cleared.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Clearing {
    /// Clears by itself once the condition is gone.
    AutoClear,
    /// Needs `clear_fault`.
    ManualClear,
    /// Persists until power cycle or service.
    NonClearable,
    Other(&'static str),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ErrorInfo {
    pub code: u16,
    pub name: &'static str,
    pub severity: Severity,
    pub clearing: Clearing,
    pub title: &'static str,
    pub description: &'static str,
    pub remedy: &'static str,
}

impl std::fmt::Display for ErrorInfo {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{} ({:?}, {:?}): {}", self.name, self.severity, self.clearing, self.title)
    }
}

/// Look up an error code; `None` for 0 (no error) and unknown codes.
pub fn describe(code: u16) -> Option<&'static ErrorInfo> {
    TABLE.iter().find(|e| e.code == code)
}

/// Name of an error code, or `"none"` / `"unknown(<code>)"`.
pub fn name(code: u16) -> String {
    match code {
        0 => "none".into(),
        c => describe(c).map(|e| e.name.to_string()).unwrap_or_else(|| format!("unknown({c})")),
    }
}

